{"file_path":"src/eval.js","content":"import { parseAddress, indexToCol } from './sheet.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })

// ---------- parsing ----------
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: parseFloat(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=)/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += 2; continue
    }
    if ('^*/+-=<>():,'.includes(c)) { toks.push({ k: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('parse') }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  function expr() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p]
    if (t.k === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = expr()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = [expr()]
        while (isOp(',')) { p++; args.push(expr()) }
        if (!isOp(')')) fail()
        p++
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        if (p >= toks.length || toks[p].k !== 'word') fail()
        const t2 = toks[p++]
        return { type: 'range', a: t.v, b: t2.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { type: 'bool', v: true }
      if (u === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', a: t.v }
    }
    fail()
  }
  try {
    const e = expr()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

// ---------- cell model ----------
function classify(cell) {
  if (cell.cls) return cell.cls
  const c = cell.content
  let cls
  if (c.startsWith('=')) cls = { kind: 'formula', ast: parseFormula(c.slice(1)) }
  else if (c === '') cls = { kind: 'lit', value: num(0) }
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) cls = { kind: 'lit', value: num(parseFloat(c)) }
  else if (ERRORS.has(c)) cls = { kind: 'lit', value: err(c) }
  else cls = { kind: 'lit', value: { t: 's', v: c } }
  cell.cls = cls
  return cls
}

function rangeCells(node) {
  const a = parseAddress(node.a)
  const b = parseAddress(node.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(c * 1000 + r)
  return out
}

export function depsOf(cell) {
  const cls = classify(cell)
  if (cls.kind !== 'formula' || !cls.ast) return []
  const keys = new Set()
  const walk = (n) => {
    switch (n.type) {
      case 'ref': { const a = parseAddress(n.a); if (a) keys.add(a.key); break }
      case 'range': { const l = rangeCells(n); if (l) l.forEach((k) => keys.add(k)); break }
      case 'bin': walk(n.l); walk(n.r); break
      case 'neg': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(cls.ast)
  return [...keys].sort((x, y) => x - y).map((k) => indexToCol(Math.floor(k / 1000)) + (k % 1000))
}

// ---------- evaluation ----------
function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}

const rank = { n: 0, s: 1, b: 2 }
function cmpText(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cmpText(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

export function evaluateAll(cells) {
  const byKey = new Map(cells.map((c) => [c.key, c]))
  const memo = new Map()
  const visiting = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const cell = byKey.get(key)
