export function evaluateAll(cells) {
  const byKey = new Map(cells.map((c) => [c.key, c]))
  const memo = new Map()
  const visiting = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const cell = byKey.get(key)
    if (!cell) return num(0)
    if (visiting.has(key)) return err('#CYCLE!')
    const cls = classify(cell)
    let v
    if (cls.kind === 'lit') v = cls.value
    else if (!cls.ast) v = err('#ERR!')
    else {
      visiting.add(key)
      v = evalNode(cls.ast)
      visiting.delete(key)
      if (v.t === 'range') v = err('#ERR!')
    }
    memo.set(key, v)
    return v
  }

  function finite(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

  function collect(args) {
    const vals = []
    for (const a of args) {
      if (a.type === 'range') {
        const l = rangeCells(a)
        if (!l) vals.push(err('#REF!'))
        else for (const k of l) vals.push(cellValue(k))
      } else vals.push(evalNode(a))
    }
    return vals
  }

  function evalNode(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': {
        const a = parseAddress(n.a)
        return a ? cellValue(a.key) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'neg': {
        const v = evalNode(n.e)
        if (v.t === 'e') return v
        const x = toNum(v)
        if (x.t === 'e') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': {
        const l = evalNode(n.l)
        if (l.t === 'e') return l
        const r = evalNode(n.r)
        if (r.t === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'b', v: res }
        }
        const a = toNum(l)
        if (a.t === 'e') return a
        const b = toNum(r)
        if (b.t === 'e') return b
        switch (n.op) {
          case '+': return finite(a.v + b.v)
          case '-': return finite(a.v - b.v)
          case '*': return finite(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
          case '^': return finite(Math.pow(a.v, b.v))
        }
        return err('#ERR!')
      }
      case 'call': return call(n)
    }
    return err('#ERR!')
  }

  function call(n) {
    const name = n.name
    const args = n.args
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) {
      const vals = collect(args)
      const e = vals.find((v) => v.t === 'e')
      if (e) return e
      if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
      const nums = []
      for (const v of vals) {
        const x = toNum(v)
        if (x.t === 'e') return x
        nums.push(x.v)
      }
      if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
      if (name === 'AVG') return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
      if (name === 'MIN') return num(Math.min(...nums))
      return num(Math.max(...nums))
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      if (args[0].type === 'range') return err('#ERR!')
      const v = evalNode(args[0])
      if (v.t === 'e') return v
      const x = toNum(v)
      return x.t === 'e' ? x : num(Math.abs(x.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const c = evalNode(args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return evalNode(truth ? args[1] : args[2])
    }
    return err('#NAME?')
  }

  for (const c of cells) cellValue(c.key)
  return memo
}

export function formatValue(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)) + 0)
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}
